import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Ricordi di un noioso professore","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lcfaa.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lcfaa.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lcfaa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ricordi-di-un-noioso-professore" tabindex="-1">Ricordi di un noioso professore <a class="header-anchor" href="#ricordi-di-un-noioso-professore" aria-label="Permalink to “Ricordi di un noioso professore”">​</a></h1><p>Eravamo circa alla metà degli anni <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70</mn></mrow><annotation encoding="application/x-tex">70</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">70</span></span></span></span> ed insegnavo matematica applicata ad un Istituto Tecnico Commerciale a Cagli.</p><p>Avevo una classe quarta molto intelligente, ma piuttosto svagata e poco disposta ad impegnarsi seriamente. Era un venerdì di metà marzo e cercavo di spiegare appunto le probabilità ed i primi rudimenti di statistica. La classe non solo non mi seguiva, ma sembrava occupata in altre faccende: osservando con più attenzione mi sono accorto che l&#39;impegno degli alunni era di compilare un pacco di schedine del totocalcio.</p><p>Sequestro le schede, faccio una paternale, e provo a riprendere l&#39;argomento, ma mi accorgo che lo scrivere di nascosto le schedine continua.</p><p>Capisco che l&#39;argomento teorico è noioso e che sarebbe inutile insistere, mi viene un&#39;idea: dico alla classe:</p><p><em>&quot;Visto che volete fare la schedina, almeno facciamola con metodo statistico applicando la probabilità soggettiva:</em></p><p><em>Lupini venga alla lavagna e scriva la prima partita.</em></p><p><em>Ora vi chiamerò uno per uno: se pensate che vinca la prima squadra Lupini farà un segno sulla casella dell&#39;uno se pensate che vinca la seconda il segno verrà fatto sulla casella del due. Se pensate ad un pareggio facciamo due segni, uno sull&#39;uno e l&#39;altro sul due</em></p><p><em>Alla fine contiamo i segni e facciamo la percentuale fra i segni dell&#39;uno e tutti i segni: se la percentuale è superiore al <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">70\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">70%</span></span></span></span> mettiamo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>, se è inferiore al <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>30</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">30\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">30%</span></span></span></span> mettiamo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> e se invece è compresa fra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>40</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">40\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">40%</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>60</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">60\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">60%</span></span></span></span> mettiamo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>; negli altri casi mettiamo entrambi i risultati (se ad esempio viene tra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>30</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">30\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">30%</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>40</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">40\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">40%</span></span></span></span> mettiamo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mtext>\xA0</mtext><mn>2</mn></mrow><annotation encoding="application/x-tex">x \\ 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord mathnormal">x</span><span class="mspace">\xA0</span><span class="mord">2</span></span></span></span>, se viene tra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>60</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">60\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">60%</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">70\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">70%</span></span></span></span> mettiamo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mtext>\xA0</mtext><mi>x</mi></mrow><annotation encoding="application/x-tex">1 \\ x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span><span class="mspace">\xA0</span><span class="mord mathnormal">x</span></span></span></span>)&quot;</em></p><p>Attirata così la loro attenzione ho chiarito meglio il concetto di probabilità soggettiva e, quando hanno capito bene, abbiamo compilato la schedina, fatte le percentuali e completato un sistema giusto in tempo prima che suonasse la campanella.</p><p>Appena finito Lupini è saltato su: <em>&quot;Adesso fuori <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>200</mn></mrow><annotation encoding="application/x-tex">200</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">200</span></span></span></span> lire per uno che ce lo giochiamo&quot;</em>.</p><p>Così ognuno di noi ha tirato fuori le <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>200</mn></mrow><annotation encoding="application/x-tex">200</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">200</span></span></span></span> lire.</p><p>Il lunedì successivo appena arrivato a scuola sono stato circondato dagli alunni: avevamo fatto un <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>12</mn></mrow><annotation encoding="application/x-tex">12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">12</span></span></span></span> e qualche <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>11</mn></mrow><annotation encoding="application/x-tex">11</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">11</span></span></span></span>; ricordo che la vincita era di circa <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>400.000</mn></mrow><annotation encoding="application/x-tex">400.000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">400.000</span></span></span></span> lire (in pratica più del mio stipendio di due mesi); il genitore di un alunno si incaricò di ritirare la vincita ad Ancona ed a trasformarla in calcolatrici elettroniche: una per ogni alunno della classe ed una per me.</p><blockquote><p><strong>Nota:</strong> Le calcolatrici erano molto costose e da poco avevano cominciato a circolare in Italia.</p></blockquote><p>Misi in un cassetto il mio regolo calcolatore e preparai la lezione successiva sull&#39;uso della calcolatrice.</p><p>Quella fu l&#39;unica volta che vinsi qualcosa al totocalcio.</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};